-- ============================================================

-- MHIDA English course — curriculum seed (10 weeks, CEFR A1)

-- 'Open Frequency English' for MHIDA doctor members.

-- Run AFTER migration10_course.sql. Safe to re-run: it only

-- inserts weeks that do not exist yet.

-- ============================================================

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 1, 1, 'Hello! Greetings & Introductions', 'Мэндчилгээ ба танилцах', '{"objectives": ["Greet people formally and informally", "Introduce yourself with your name and job", "Say goodbye politely", "Use ''I am'' and ''My name is'' correctly"], "dialogue": [{"speaker": "Dr. Bat", "en": "Good morning! My name is Bat.", "mn": "Өглөөний мэнд! Намайг Бат гэдэг."}, {"speaker": "Dr. Sara", "en": "Good morning, Bat. I am Sara. Nice to meet you.", "mn": "Өглөөний мэнд, Бат. Би Сара. Танилцахад таатай байна."}, {"speaker": "Dr. Bat", "en": "Nice to meet you too. Are you a doctor?", "mn": "Танилцахад таатай байна. Та эмч үү?"}, {"speaker": "Dr. Sara", "en": "Yes, I am. I am an insurance doctor.", "mn": "Тийм ээ. Би даатгалын эмч."}, {"speaker": "Dr. Bat", "en": "Great! Welcome to our hospital.", "mn": "Сайхан байна! Манай эмнэлэгт тавтай морил."}, {"speaker": "Dr. Sara", "en": "Thank you very much.", "mn": "Маш их баярлалаа."}, {"speaker": "Dr. Bat", "en": "See you later, Sara.", "mn": "Дараа уулзъя, Сара."}, {"speaker": "Dr. Sara", "en": "Goodbye!", "mn": "Баяртай!"}], "vocab": [{"en": "hello / hi", "mn": "сайн уу", "example": "Hello, Doctor!"}, {"en": "good morning", "mn": "өглөөний мэнд", "example": "Good morning, everyone."}, {"en": "my name is …", "mn": "намайг … гэдэг", "example": "My name is Oyunaa."}, {"en": "nice to meet you", "mn": "танилцахад таатай байна", "example": "Nice to meet you, Dr. Lee."}, {"en": "doctor", "mn": "эмч", "example": "I am a doctor."}, {"en": "hospital", "mn": "эмнэлэг", "example": "Our hospital is big."}, {"en": "welcome", "mn": "тавтай морил", "example": "Welcome to Ulaanbaatar."}, {"en": "thank you", "mn": "баярлалаа", "example": "Thank you very much."}, {"en": "goodbye", "mn": "баяртай", "example": "Goodbye! See you tomorrow."}, {"en": "see you later", "mn": "дараа уулзъя", "example": "See you later!"}], "grammar": {"title": "Verb ''to be'': I am / You are", "body": "Use ''am'' with I, and ''are'' with you. Questions change the word order.", "examples": ["I am a doctor. → Би эмч.", "You are a nurse. → Та сувилагч.", "Are you a doctor? — Yes, I am. → Та эмч үү? — Тийм."]}, "speaking": ["Introduce yourself out loud: name + job + workplace. Repeat 3 times.", "Greet a colleague in English today and say ''Nice to meet you''.", "Record yourself saying the dialogue lines of Dr. Sara.", "Practice: ''I am an insurance doctor at … hospital.''", "Say goodbye three different ways: Goodbye / See you later / Bye."], "quiz": [{"q": "Which is a morning greeting?", "options": ["Good night", "Good morning", "Goodbye", "See you"], "answer": 1}, {"q": "''Namaig Bat gedeg'' in English is…", "options": ["I am fine", "My name is Bat", "You are Bat", "He is Bat"], "answer": 1}, {"q": "I ___ a doctor.", "options": ["are", "is", "am", "be"], "answer": 2}, {"q": "___ you a doctor? — Yes, I am.", "options": ["Am", "Is", "Do", "Are"], "answer": 3}, {"q": "''Танилцахад таатай байна'' means…", "options": ["See you later", "Nice to meet you", "Thank you", "Welcome"], "answer": 1}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 1 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 2, 1, 'About Me: Personal Information', 'Миний тухай: Хувийн мэдээлэл', '{"objectives": ["Say where you are from and where you live", "Talk about your job and workplace", "Ask simple questions about another person", "Spell your name in English"], "dialogue": [{"speaker": "Anna", "en": "Where are you from, Oyunaa?", "mn": "Оюунаа, та хаанаас ирсэн бэ?"}, {"speaker": "Oyunaa", "en": "I am from Mongolia. I live in Ulaanbaatar.", "mn": "Би Монголоос ирсэн. Улаанбаатарт амьдардаг."}, {"speaker": "Anna", "en": "What do you do?", "mn": "Та ямар ажил хийдэг вэ?"}, {"speaker": "Oyunaa", "en": "I am an insurance doctor. I work at a general hospital.", "mn": "Би даатгалын эмч. Нэгдсэн эмнэлэгт ажилладаг."}, {"speaker": "Anna", "en": "How do you spell your name?", "mn": "Таны нэрийг хэрхэн үсэглэх вэ?"}, {"speaker": "Oyunaa", "en": "O-Y-U-N-A-A.", "mn": "О-Ю-У-Н-А-А."}, {"speaker": "Anna", "en": "That is a beautiful name.", "mn": "Сайхан нэр байна."}, {"speaker": "Oyunaa", "en": "Thank you!", "mn": "Баярлалаа!"}], "vocab": [{"en": "country", "mn": "улс", "example": "Mongolia is my country."}, {"en": "city", "mn": "хот", "example": "Ulaanbaatar is a big city."}, {"en": "I am from …", "mn": "би …-аас ирсэн", "example": "I am from Mongolia."}, {"en": "I live in …", "mn": "би …-д амьдардаг", "example": "I live in Darkhan."}, {"en": "job / work", "mn": "ажил", "example": "I like my job."}, {"en": "I work at …", "mn": "би …-д ажилладаг", "example": "I work at a hospital."}, {"en": "nurse", "mn": "сувилагч", "example": "The nurse is kind."}, {"en": "colleague", "mn": "хамтран ажиллагч", "example": "My colleagues are friendly."}, {"en": "spell", "mn": "үсэглэх", "example": "How do you spell it?"}, {"en": "age", "mn": "нас", "example": "What is your age?"}], "grammar": {"title": "Questions with ''Where'' and ''What''", "body": "''Where'' asks about place. ''What'' asks about things or jobs. The verb comes after the question word.", "examples": ["Where are you from? → Та хаанаас ирсэн бэ?", "What do you do? → Та юу хийдэг вэ?", "Where do you work? → Та хаана ажилладаг вэ?"]}, "speaking": ["Answer aloud: Where are you from? Where do you live? What do you do?", "Spell your own name letter by letter in English.", "Describe a colleague: ''She is a nurse. She works at …''.", "Ask a family member two questions in English.", "Say your full introduction: name, city, job, workplace — 30 seconds."], "quiz": [{"q": "___ are you from?", "options": ["What", "Where", "Who", "How"], "answer": 1}, {"q": "I ___ in Ulaanbaatar.", "options": ["live", "lives", "living", "am live"], "answer": 0}, {"q": "''Би эмнэлэгт ажилладаг'' is…", "options": ["I work at a hospital", "I live in a hospital", "I am a hospital", "I go to hospital"], "answer": 0}, {"q": "What do you ___? — I am a doctor.", "options": ["work", "job", "do", "make"], "answer": 2}, {"q": "How do you ___ your name?", "options": ["say", "spell", "speak", "tell"], "answer": 1}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 2 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 3, 1, 'Numbers, Time & Dates', 'Тоо, цаг, огноо', '{"objectives": ["Count and use numbers 1–100", "Tell the time", "Say days of the week and dates", "Make a simple appointment time"], "dialogue": [{"speaker": "Reception", "en": "Good afternoon. When is your appointment?", "mn": "Өдрийн мэнд. Таны цаг хэдэн цагт вэ?"}, {"speaker": "Patient", "en": "At three o''clock on Monday.", "mn": "Даваа гарагийн 3 цагт."}, {"speaker": "Reception", "en": "Today is Friday. Your appointment is in three days.", "mn": "Өнөөдөр баасан. Таны цаг гурав хоногийн дараа."}, {"speaker": "Patient", "en": "What time is it now?", "mn": "Одоо хэдэн цаг болж байна?"}, {"speaker": "Reception", "en": "It is half past two.", "mn": "Хоёр цаг хагас."}, {"speaker": "Patient", "en": "Thank you. See you on Monday.", "mn": "Баярлалаа. Даваа гарагт уулзъя."}, {"speaker": "Reception", "en": "See you. Have a nice day!", "mn": "Уулзъя. Сайхан өдөр өнгөрүүлээрэй!"}], "vocab": [{"en": "one, two, three…", "mn": "нэг, хоёр, гурав…", "example": "I have two children."}, {"en": "o''clock", "mn": "цаг (бүтэн)", "example": "It is nine o''clock."}, {"en": "half past …", "mn": "… цаг хагас", "example": "It is half past two."}, {"en": "Monday–Sunday", "mn": "Даваа–Ням", "example": "Monday is the first day."}, {"en": "today", "mn": "өнөөдөр", "example": "Today is Tuesday."}, {"en": "tomorrow", "mn": "маргааш", "example": "See you tomorrow."}, {"en": "appointment", "mn": "цаг (уулзалтын)", "example": "I have an appointment at 10."}, {"en": "week", "mn": "долоо хоног", "example": "One week has seven days."}, {"en": "month", "mn": "сар", "example": "January is the first month."}, {"en": "What time is it?", "mn": "Хэдэн цаг болж байна?", "example": "What time is it now?"}], "grammar": {"title": "Prepositions of time: at / on / in", "body": "Use AT with clock times, ON with days, IN with months and years.", "examples": ["at 3 o''clock → 3 цагт", "on Monday → даваа гарагт", "in January → 1-р сард"]}, "speaking": ["Count aloud from 1 to 20, then by tens to 100.", "Say today''s day and date in English.", "Tell the current time out loud every hour today.", "Practice: ''My appointment is at … on …''.", "Say your birthday: ''My birthday is in (month)''."], "quiz": [{"q": "It is 2:30. → It is ___.", "options": ["two thirty o''clock", "half past two", "two and half", "thirty past two"], "answer": 1}, {"q": "Your appointment is ___ Monday.", "options": ["in", "at", "on", "to"], "answer": 2}, {"q": "The meeting is ___ 9 o''clock.", "options": ["on", "in", "at", "by"], "answer": 2}, {"q": "''Маргааш'' means…", "options": ["today", "yesterday", "tomorrow", "week"], "answer": 2}, {"q": "How many days are in a week?", "options": ["five", "six", "seven", "ten"], "answer": 2}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 3 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 4, 1, 'My Family & People', 'Гэр бүл ба хүмүүс', '{"objectives": ["Name family members", "Describe people simply", "Use ''have / has''", "Talk about ages"], "dialogue": [{"speaker": "Tuya", "en": "Do you have a big family, John?", "mn": "Жон, та том гэр бүлтэй юу?"}, {"speaker": "John", "en": "Yes. I have a wife and two children.", "mn": "Тийм. Би эхнэр, хоёр хүүхэдтэй."}, {"speaker": "Tuya", "en": "How old are your children?", "mn": "Хүүхдүүд тань хэдэн настай вэ?"}, {"speaker": "John", "en": "My son is ten and my daughter is seven.", "mn": "Хүү маань арван настай, охин маань долоон настай."}, {"speaker": "Tuya", "en": "I have one brother. He is a doctor too.", "mn": "Би нэг ахтай. Тэр бас эмч."}, {"speaker": "John", "en": "Really? Doctors are in your family!", "mn": "Тийм үү? Танай гэр бүл эмч нэртэй юм!"}, {"speaker": "Tuya", "en": "Yes, my mother is a nurse.", "mn": "Тийм ээ, ээж маань сувилагч."}], "vocab": [{"en": "family", "mn": "гэр бүл", "example": "My family is small."}, {"en": "mother / father", "mn": "ээж / аав", "example": "My mother is a nurse."}, {"en": "wife / husband", "mn": "эхнэр / нөхөр", "example": "His wife is a teacher."}, {"en": "son / daughter", "mn": "хүү / охин", "example": "My daughter is seven."}, {"en": "brother / sister", "mn": "ах, дүү (эр) / эгч, дүү (эм)", "example": "I have one brother."}, {"en": "children", "mn": "хүүхдүүд", "example": "They have three children."}, {"en": "How old …?", "mn": "хэдэн настай …?", "example": "How old is your son?"}, {"en": "years old", "mn": "настай", "example": "I am forty years old."}, {"en": "tall / short", "mn": "өндөр / намхан", "example": "My father is tall."}, {"en": "kind", "mn": "эелдэг", "example": "The nurse is kind."}], "grammar": {"title": "have / has", "body": "Use HAVE with I, you, we, they. Use HAS with he, she, it.", "examples": ["I have two children. → Би хоёр хүүхэдтэй.", "She has one brother. → Тэр нэг ахтай.", "Do you have a family? → Та гэр бүлтэй юу?"]}, "speaking": ["Describe your family in 5 sentences out loud.", "Say the ages of three family members.", "Describe one colleague: tall/short, kind, job.", "Ask someone: ''Do you have children? How old are they?''", "Show a family photo and name everyone in English."], "quiz": [{"q": "She ___ two children.", "options": ["have", "has", "haves", "is"], "answer": 1}, {"q": "''Охин'' means…", "options": ["son", "wife", "daughter", "sister"], "answer": 2}, {"q": "How ___ is your son? — He is ten.", "options": ["old", "age", "year", "many"], "answer": 0}, {"q": "I ___ one brother.", "options": ["has", "am", "have", "is"], "answer": 2}, {"q": "My father is a doctor, and my mother is a ___.", "options": ["hospital", "nurse", "family", "children"], "answer": 1}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 4 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 5, 1, 'A Doctor''s Day: Daily Routines', 'Эмчийн өдөр: Өдөр тутмын үйл', '{"objectives": ["Describe your daily routine", "Use present simple verbs", "Say how often you do things", "Talk about your work schedule"], "dialogue": [{"speaker": "Amar", "en": "What time do you get up, Dr. Kim?", "mn": "Доктор Ким, та хэдэн цагт босдог вэ?"}, {"speaker": "Dr. Kim", "en": "I get up at six. I start work at eight.", "mn": "Би зургаан цагт босдог. Наймд ажлаа эхэлдэг."}, {"speaker": "Amar", "en": "Do you see many patients?", "mn": "Та олон өвчтөн үздэг үү?"}, {"speaker": "Dr. Kim", "en": "Yes, I see about twenty patients every day.", "mn": "Тийм, өдөрт ойролцоогоор хорин өвчтөн үздэг."}, {"speaker": "Amar", "en": "When do you finish work?", "mn": "Та хэдэн цагт ажлаа дуусгадаг вэ?"}, {"speaker": "Dr. Kim", "en": "At five. Then I have dinner with my family.", "mn": "Тавд. Дараа нь гэр бүлтэйгээ оройн хоол иддэг."}, {"speaker": "Amar", "en": "You work hard!", "mn": "Та шаргуу ажилладаг юм!"}], "vocab": [{"en": "get up", "mn": "босох", "example": "I get up at 6."}, {"en": "start work", "mn": "ажил эхлэх", "example": "I start work at 8."}, {"en": "finish work", "mn": "ажил дуусгах", "example": "I finish work at 5."}, {"en": "every day", "mn": "өдөр бүр", "example": "I check emails every day."}, {"en": "patient", "mn": "өвчтөн", "example": "The patient is waiting."}, {"en": "see a patient", "mn": "өвчтөн үзэх", "example": "I see patients in the morning."}, {"en": "have lunch", "mn": "өдрийн хоол идэх", "example": "We have lunch at noon."}, {"en": "go home", "mn": "гэртээ харих", "example": "I go home at six."}, {"en": "usually", "mn": "ихэвчлэн", "example": "I usually work on Mondays."}, {"en": "sometimes", "mn": "заримдаа", "example": "Sometimes I work late."}], "grammar": {"title": "Present Simple: I work / She works", "body": "For routines, use the base verb. Add -s for he/she/it. Questions use do/does.", "examples": ["I see patients every day. → Би өдөр бүр өвчтөн үздэг.", "She works at a clinic. → Тэр эмнэлэгт ажилладаг.", "What time do you get up? → Та хэдэн цагт босдог вэ?"]}, "speaking": ["Describe your day from morning to night — 8 sentences.", "Say your work schedule: start time, lunch, finish time.", "Use ''usually'' and ''sometimes'' in two true sentences.", "Ask a colleague: ''What time do you start work?''", "Describe a colleague''s routine using he/she + verb-s."], "quiz": [{"q": "I ___ up at six o''clock.", "options": ["gets", "get", "getting", "got"], "answer": 1}, {"q": "She ___ at a general hospital.", "options": ["work", "works", "working", "is work"], "answer": 1}, {"q": "''Өвчтөн'' means…", "options": ["nurse", "medicine", "patient", "doctor"], "answer": 2}, {"q": "What time ___ you finish work?", "options": ["are", "does", "is", "do"], "answer": 3}, {"q": "I ___ work late.", "options": ["sometimes", "sometime", "always am", "usually am"], "answer": 0}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 5 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 6, 1, 'In the Hospital: Places & Directions', 'Эмнэлэгт: Байршил ба чиглэл', '{"objectives": ["Name hospital departments and places", "Give and understand simple directions", "Use ''there is / there are''", "Help a visitor find a room"], "dialogue": [{"speaker": "Visitor", "en": "Excuse me, where is the pharmacy?", "mn": "Уучлаарай, эмийн сан хаана байдаг вэ?"}, {"speaker": "Dr. Bold", "en": "It is on the first floor, next to reception.", "mn": "Нэг давхарт, бүртгэлийн хажууд байгаа."}, {"speaker": "Visitor", "en": "And where is Room 205?", "mn": "205 тоот өрөө хаана вэ?"}, {"speaker": "Dr. Bold", "en": "Go straight, then turn left. It is on the second floor.", "mn": "Чигээрээ яваад зүүн тийш эргэ. Хоёр давхарт байгаа."}, {"speaker": "Visitor", "en": "Is there an elevator?", "mn": "Цахилгаан шат байгаа юу?"}, {"speaker": "Dr. Bold", "en": "Yes, there is. It is behind you.", "mn": "Тийм, байгаа. Таны ард байна."}, {"speaker": "Visitor", "en": "Thank you so much!", "mn": "Маш их баярлалаа!"}], "vocab": [{"en": "reception", "mn": "бүртгэл, хүлээн авах", "example": "Ask at reception."}, {"en": "pharmacy", "mn": "эмийн сан", "example": "The pharmacy is downstairs."}, {"en": "laboratory", "mn": "лаборатори", "example": "The laboratory is on the third floor."}, {"en": "emergency room", "mn": "яаралтай тусламж", "example": "Go to the emergency room!"}, {"en": "floor", "mn": "давхар", "example": "My office is on the second floor."}, {"en": "turn left / right", "mn": "зүүн / баруун тийш эргэх", "example": "Turn right at the door."}, {"en": "go straight", "mn": "чигээрээ явах", "example": "Go straight ahead."}, {"en": "next to", "mn": "хажууд", "example": "The lab is next to the pharmacy."}, {"en": "behind", "mn": "ард", "example": "The elevator is behind you."}, {"en": "elevator / stairs", "mn": "цахилгаан шат / шат", "example": "Take the stairs."}], "grammar": {"title": "There is / There are", "body": "Use ''there is'' for one thing, ''there are'' for many. Questions: Is there…? Are there…?", "examples": ["There is an elevator. → Цахилгаан шат байгаа.", "There are two laboratories. → Хоёр лаборатори байгаа.", "Is there a pharmacy? → Эмийн сан байгаа юу?"]}, "speaking": ["Name five places in your hospital in English.", "Give directions from the entrance to your office out loud.", "Practice: ''It is on the … floor, next to …''.", "Ask and answer: ''Is there a pharmacy in your hospital?''", "Draw a simple map of your workplace and describe it."], "quiz": [{"q": "___ there an elevator? — Yes, there is.", "options": ["Are", "Is", "Do", "Have"], "answer": 1}, {"q": "The pharmacy is ___ to reception.", "options": ["behind", "next", "on", "in"], "answer": 1}, {"q": "''Зүүн тийш эргэ'' means…", "options": ["go straight", "turn right", "turn left", "go up"], "answer": 2}, {"q": "There ___ two laboratories.", "options": ["is", "are", "be", "has"], "answer": 1}, {"q": "My office is ___ the second floor.", "options": ["at", "in", "on", "by"], "answer": 2}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 6 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 7, 1, 'Food & Healthy Habits', 'Хоол ба эрүүл дадал', '{"objectives": ["Talk about food and drinks", "Say what you like and don''t like", "Give simple health advice", "Use ''should'' for advice"], "dialogue": [{"speaker": "Dr. Suvd", "en": "Do you eat breakfast every day?", "mn": "Та өдөр бүр өглөөний цай уудаг уу?"}, {"speaker": "Patient", "en": "No, I don''t. I only drink coffee.", "mn": "Үгүй. Би зөвхөн кофе уудаг."}, {"speaker": "Dr. Suvd", "en": "You should eat breakfast. It is important.", "mn": "Та өглөөний цай уух хэрэгтэй. Энэ чухал."}, {"speaker": "Patient", "en": "What should I eat?", "mn": "Би юу идэх хэрэгтэй вэ?"}, {"speaker": "Dr. Suvd", "en": "Eat fruit and drink water. Don''t drink too much coffee.", "mn": "Жимс идэж, ус ууж байгаарай. Хэт их кофе уухгүй байх."}, {"speaker": "Patient", "en": "OK. I like apples.", "mn": "За. Би алимд дуртай."}, {"speaker": "Dr. Suvd", "en": "Perfect. Apples are healthy.", "mn": "Маш сайн. Алим эрүүл мэндэд сайн."}], "vocab": [{"en": "breakfast / lunch / dinner", "mn": "өглөөний / өдрийн / оройн хоол", "example": "I have lunch at noon."}, {"en": "eat / drink", "mn": "идэх / уух", "example": "Drink more water."}, {"en": "water", "mn": "ус", "example": "Water is good for you."}, {"en": "fruit / vegetables", "mn": "жимс / хүнсний ногоо", "example": "Eat more vegetables."}, {"en": "meat", "mn": "мах", "example": "We eat meat in winter."}, {"en": "tea / coffee", "mn": "цай / кофе", "example": "Mongolian milk tea is famous."}, {"en": "healthy", "mn": "эрүүл", "example": "This food is healthy."}, {"en": "I like …", "mn": "би …-д дуртай", "example": "I like apples."}, {"en": "I don''t like …", "mn": "би …-д дургүй", "example": "I don''t like fast food."}, {"en": "should", "mn": "хэрэгтэй (зөвлөгөө)", "example": "You should sleep more."}], "grammar": {"title": "should / shouldn''t for advice", "body": "Doctors give advice with ''should''. Negative: shouldn''t (= should not).", "examples": ["You should drink water. → Та ус уух хэрэгтэй.", "You shouldn''t smoke. → Та тамхи татаж болохгүй.", "What should I eat? → Би юу идэх хэрэгтэй вэ?"]}, "speaking": ["Say three foods you like and two you don''t like.", "Give three pieces of advice to a patient with ''should''.", "Describe your breakfast in English.", "Practice: ''You should… / You shouldn''t…'' — 5 sentences.", "Tell a family member one healthy habit in English."], "quiz": [{"q": "You ___ drink more water.", "options": ["should", "are", "do", "have"], "answer": 0}, {"q": "''Жимс'' means…", "options": ["meat", "fruit", "water", "tea"], "answer": 1}, {"q": "I ___ like fast food.", "options": ["no", "not", "don''t", "am not"], "answer": 2}, {"q": "You ___ smoke. It is bad for you.", "options": ["should", "shouldn''t", "do", "must to"], "answer": 1}, {"q": "Which is the morning meal?", "options": ["dinner", "lunch", "breakfast", "snack"], "answer": 2}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 7 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 8, 1, 'The Body & Simple Symptoms', 'Бие ба энгийн шинж тэмдэг', '{"objectives": ["Name parts of the body", "Ask ''What''s the matter?''", "Describe simple symptoms", "Respond with simple advice"], "dialogue": [{"speaker": "Dr. Erdene", "en": "Good morning. What''s the matter?", "mn": "Өглөөний мэнд. Юу нь болохгүй байна вэ?"}, {"speaker": "Patient", "en": "I have a headache and a sore throat.", "mn": "Толгой өвдөж, хоолой хорсож байна."}, {"speaker": "Dr. Erdene", "en": "Do you have a fever?", "mn": "Халуурч байна уу?"}, {"speaker": "Patient", "en": "Yes, a little. And my back hurts.", "mn": "Тийм, бага зэрэг. Бас нуруу өвдөж байна."}, {"speaker": "Dr. Erdene", "en": "How long have you felt this way?", "mn": "Хэдий хугацаанд ийм байна вэ?"}, {"speaker": "Patient", "en": "For two days.", "mn": "Хоёр хоног болж байна."}, {"speaker": "Dr. Erdene", "en": "OK. Rest, drink warm water, and take this medicine.", "mn": "За. Амарч, бүлээн ус ууж, энэ эмийг уугаарай."}], "vocab": [{"en": "head / headache", "mn": "толгой / толгой өвдөх", "example": "I have a headache."}, {"en": "throat / sore throat", "mn": "хоолой / хоолой хорсох", "example": "My throat is sore."}, {"en": "stomach", "mn": "гэдэс", "example": "My stomach hurts."}, {"en": "back", "mn": "нуруу", "example": "My back hurts."}, {"en": "fever", "mn": "халуун", "example": "The child has a fever."}, {"en": "cough", "mn": "ханиалга", "example": "I have a bad cough."}, {"en": "hurt", "mn": "өвдөх", "example": "Where does it hurt?"}, {"en": "medicine", "mn": "эм", "example": "Take this medicine twice a day."}, {"en": "rest", "mn": "амрах", "example": "You should rest."}, {"en": "What''s the matter?", "mn": "Юу нь болохгүй байна вэ?", "example": "What''s the matter today?"}], "grammar": {"title": "have + symptom / … hurts", "body": "Use ''I have a …'' for symptoms, and ''(body part) hurts'' for pain.", "examples": ["I have a headache. → Толгой өвдөж байна.", "My back hurts. → Нуруу өвдөж байна.", "Do you have a fever? → Халуурч байна уу?"]}, "speaking": ["Point to five body parts and name them in English.", "Practice the doctor''s questions: ''What''s the matter? Do you have a fever?''", "Describe two symptoms with ''I have a …''.", "Role-play the full dialogue — both roles, out loud.", "Give advice for a cold: three sentences with ''should''."], "quiz": [{"q": "''Толгой өвдөж байна'' is…", "options": ["I have a fever", "I have a headache", "My back hurts", "I have a cough"], "answer": 1}, {"q": "My back ___.", "options": ["hurt", "hurting", "hurts", "is hurt"], "answer": 2}, {"q": "Do you have a ___? — Yes, 38.5°C.", "options": ["cough", "fever", "headache", "medicine"], "answer": 1}, {"q": "Take this ___ twice a day.", "options": ["rest", "water", "medicine", "food"], "answer": 2}, {"q": "What''s the ___? — I feel sick.", "options": ["problem you", "matter", "wrong", "happen"], "answer": 1}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 8 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 9, 1, 'On the Phone: Appointments', 'Утсаар: Цаг захиалга', '{"objectives": ["Answer the phone politely", "Make and change an appointment", "Take a simple message", "Confirm details by repeating"], "dialogue": [{"speaker": "Reception", "en": "Good morning, City Hospital. How can I help you?", "mn": "Өглөөний мэнд, Хотын эмнэлэг. Танд юугаар туслах вэ?"}, {"speaker": "Caller", "en": "Hello. I would like to make an appointment, please.", "mn": "Сайн байна уу. Би цаг захиалмаар байна."}, {"speaker": "Reception", "en": "Of course. What is your name?", "mn": "Тэгэлгүй яахав. Таны нэр хэн бэ?"}, {"speaker": "Caller", "en": "My name is Ganbold. G-A-N-B-O-L-D.", "mn": "Намайг Ганболд гэдэг. Г-А-Н-Б-О-Л-Д."}, {"speaker": "Reception", "en": "Thank you. Is Tuesday at ten o''clock OK?", "mn": "Баярлалаа. Мягмар гарагийн 10 цаг болох уу?"}, {"speaker": "Caller", "en": "Yes, that is fine.", "mn": "Тийм, болно."}, {"speaker": "Reception", "en": "Great. See you on Tuesday at ten. Goodbye.", "mn": "Сайхан. Мягмарын 10 цагт уулзъя. Баяртай."}], "vocab": [{"en": "How can I help you?", "mn": "Танд юугаар туслах вэ?", "example": "Hello! How can I help you?"}, {"en": "I would like to …", "mn": "би …-маар байна", "example": "I would like to make an appointment."}, {"en": "make an appointment", "mn": "цаг захиалах", "example": "Can I make an appointment?"}, {"en": "change / cancel", "mn": "өөрчлөх / цуцлах", "example": "I need to change my appointment."}, {"en": "available", "mn": "боломжтой, сул", "example": "The doctor is available at 3."}, {"en": "Is … OK?", "mn": "… болох уу?", "example": "Is Monday OK?"}, {"en": "That is fine", "mn": "болно", "example": "Ten o''clock? That is fine."}, {"en": "message", "mn": "мэдээлэл, захиа", "example": "Can I leave a message?"}, {"en": "call back", "mn": "эргэж залгах", "example": "I will call back later."}, {"en": "Just a moment", "mn": "түр хүлээнэ үү", "example": "Just a moment, please."}], "grammar": {"title": "Polite requests: I would like… / Can I…?", "body": "''I would like…'' is a polite ''I want''. ''Can I…?'' asks permission politely.", "examples": ["I would like to make an appointment. → Би цаг захиалмаар байна.", "Can I change my appointment? → Би цагаа өөрчилж болох уу?", "Can I leave a message? → Захиа үлдээж болох уу?"]}, "speaking": ["Practice answering: ''Good morning, … hospital. How can I help you?''", "Role-play booking an appointment — both roles.", "Spell your name over an imaginary phone call.", "Practice changing an appointment: ''Can I change… to…?''", "Repeat details to confirm: ''So, Tuesday at ten. Thank you.''"], "quiz": [{"q": "I ___ like to make an appointment.", "options": ["will", "would", "should", "am"], "answer": 1}, {"q": "How can I ___ you?", "options": ["make", "give", "help", "call"], "answer": 2}, {"q": "''Цаг захиалах'' means…", "options": ["cancel an appointment", "make an appointment", "call back", "leave a message"], "answer": 1}, {"q": "___ I leave a message?", "options": ["Can", "Am", "Do", "Would to"], "answer": 0}, {"q": "Is Tuesday OK? — Yes, that is ___.", "options": ["good time", "fine", "well", "right time"], "answer": 1}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 9 and lesson_no = 1);

insert into public.course_lessons (week, lesson_no, title, title_mn, content)
select 10, 1, 'My Story: Review & Final Speaking', 'Миний түүх: Давтлага ба төгсгөлийн яриа', '{"objectives": ["Review all 10 weeks", "Tell your story: who you are, your work, your day", "Answer questions fluently at A1 level", "Complete the final speaking task"], "dialogue": [{"speaker": "Examiner", "en": "Tell me about yourself, please.", "mn": "Өөрийнхөө тухай ярина уу."}, {"speaker": "You", "en": "My name is …. I am from Mongolia. I am an insurance doctor.", "mn": "Намайг … гэдэг. Би Монголоос ирсэн. Би даатгалын эмч."}, {"speaker": "Examiner", "en": "What is your daily routine?", "mn": "Таны өдөр тутмын үйл ажиллагаа?"}, {"speaker": "You", "en": "I get up at six, start work at eight, and see patients every day.", "mn": "Би зургаад босч, наймд ажил эхэлж, өдөр бүр өвчтөн үздэг."}, {"speaker": "Examiner", "en": "What do you like about your job?", "mn": "Ажлынхаа юунд дуртай вэ?"}, {"speaker": "You", "en": "I like helping people. My colleagues are kind.", "mn": "Би хүмүүст туслах дуртай. Хамт олон маань эелдэг."}, {"speaker": "Examiner", "en": "Wonderful. Congratulations on finishing the course!", "mn": "Гайхалтай. Курс төгссөнд баяр хүргэе!"}], "vocab": [{"en": "story", "mn": "түүх", "example": "Tell me your story."}, {"en": "about myself", "mn": "өөрийн тухай", "example": "Let me tell you about myself."}, {"en": "helping people", "mn": "хүмүүст туслах", "example": "I like helping people."}, {"en": "proud", "mn": "бахархалтай", "example": "I am proud of my work."}, {"en": "learn", "mn": "сурах", "example": "I learn English every week."}, {"en": "practice", "mn": "дадлага хийх", "example": "Practice every day."}, {"en": "improve", "mn": "сайжруулах", "example": "I want to improve my English."}, {"en": "congratulations", "mn": "баяр хүргэе", "example": "Congratulations, Doctor!"}, {"en": "certificate", "mn": "гэрчилгээ", "example": "You will get a certificate."}, {"en": "future", "mn": "ирээдүй", "example": "Good luck in the future!"}], "grammar": {"title": "Review: the five key patterns", "body": "You now know five power patterns. Combine them to speak about anything at A1 level.", "examples": ["I am… / I have… → Би … / Би …-тай", "I work… I get up… (present simple) → Би ажилладаг…", "There is / are… · You should… · I would like…"]}, "speaking": ["Record a 60-second self-introduction: name, city, job, family, routine.", "Answer aloud: What do you like about your job?", "Give a patient three pieces of advice — full sentences.", "Book an imaginary appointment on the phone — full dialogue.", "Say the final dialogue as ''You'' — smooth, without reading."], "quiz": [{"q": "I am … / I have … — which is correct?", "options": ["I am two children", "I have a doctor", "I am a doctor", "I have from Mongolia"], "answer": 2}, {"q": "She ___ patients every day.", "options": ["see", "sees", "seeing", "is see"], "answer": 1}, {"q": "___ there a pharmacy here? — Yes, there is.", "options": ["Are", "Do", "Is", "Have"], "answer": 2}, {"q": "You ___ rest and drink water.", "options": ["would", "should", "are", "like"], "answer": 1}, {"q": "I ___ like to make an appointment.", "options": ["would", "should", "can", "am"], "answer": 0}]}'::jsonb
where not exists (select 1 from public.course_lessons where week = 10 and lesson_no = 1);
